<?php
namespace App\Http\Controllers;
use App\Models\{Appointment,BarberProfile,Schedule,Service,ServiceAddon,User};
use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Hash;
class AdminController extends Controller {
 public function overview(){ $appointments=Appointment::query(); return response()->json(['stats'=>['revenue'=>['daily'=>(clone $appointments)->whereDate('appointment_date',now())->whereIn('status',['confirmed','completed'])->sum('total_price'),'monthly'=>(clone $appointments)->whereMonth('appointment_date',now()->month)->whereYear('appointment_date',now()->year)->whereIn('status',['confirmed','completed'])->sum('total_price'),'yearly'=>(clone $appointments)->whereYear('appointment_date',now()->year)->whereIn('status',['confirmed','completed'])->sum('total_price')],'appointments'=>['total'=>(clone $appointments)->count(),'pending'=>(clone $appointments)->where('status','pending')->count(),'confirmed'=>(clone $appointments)->where('status','confirmed')->count(),'cancelled'=>(clone $appointments)->where('status','cancelled')->count()]],'top_services'=>Service::withCount('appointmentServices as bookings')->orderByDesc('bookings')->limit(5)->get(['id','name'])->map(fn($s)=>['name'=>$s->name,'bookings'=>$s->bookings]),'top_barbers'=>User::where('role','barber')->with('profile')->withCount('barberAppointments as bookings')->orderByDesc('bookings')->limit(5)->get()->map(fn($b)=>['id'=>$b->id,'name'=>$b->name,'rating'=>$b->profile?->rating,'bookings'=>$b->bookings])]); }
 public function barbers(){return User::where('role','barber')->with('profile')->get();}
 public function storeBarber(Request $r){$d=$r->validate(['name'=>'required|string','email'=>'required|email|unique:users,email','phone'=>'nullable|string','bio'=>'nullable|string','photo_url'=>'nullable|url']);$u=User::create(['name'=>$d['name'],'email'=>$d['email'],'phone'=>$d['phone']??null,'password'=>Hash::make('password'),'role'=>'barber']);BarberProfile::create(['user_id'=>$u->id,'bio'=>$d['bio']??null,'photo_url'=>$d['photo_url']??null]);return response()->json($u->load('profile'),201);}
 public function updateBarber(Request $r,User $barber){$d=$r->validate(['name'=>'sometimes|string','email'=>'sometimes|email|unique:users,email,'.$barber->id,'phone'=>'nullable|string','bio'=>'nullable|string','photo_url'=>'nullable|url','is_active'=>'sometimes|boolean']);$barber->update(collect($d)->only(['name','email','phone'])->all());$barber->profile()->updateOrCreate([],collect($d)->only(['bio','photo_url','is_active'])->all());return $barber->load('profile');}
 public function barberSchedules(User $barber){return Schedule::where('barber_id',$barber->id)->orderBy('day_of_week')->get();}
 public function services(){return Service::with('addons')->orderBy('name')->get();}
 public function storeService(Request $r){$d=$r->validate(['name'=>'required|string','description'=>'nullable|string','duration_minutes'=>'required|integer|min:15','price'=>'required|numeric|min:0','category'=>'nullable|string','image_url'=>'nullable|url']);return Service::create($d);}
 public function updateService(Request $r,Service $service){$service->update($r->validate(['name'=>'sometimes|string','description'=>'nullable|string','duration_minutes'=>'sometimes|integer|min:15','price'=>'sometimes|numeric|min:0','category'=>'nullable|string','image_url'=>'nullable|url','is_active'=>'sometimes|boolean']));return $service;}
 public function deleteService(Service $service){$service->delete();return response()->noContent();}
 public function storeAddon(Request $r){return ServiceAddon::create($r->validate(['service_id'=>'required|exists:services,id','name'=>'required|string','duration_minutes'=>'required|integer|min:0','price'=>'required|numeric|min:0']));}
 public function updateAddon(Request $r,ServiceAddon $addon){$addon->update($r->validate(['name'=>'sometimes|string','duration_minutes'=>'sometimes|integer|min:0','price'=>'sometimes|numeric|min:0']));return $addon;}
 public function deleteAddon(ServiceAddon $addon){$addon->delete();return response()->noContent();}
 public function appointments(Request $r){return Appointment::with(['client','barber','services.service'])->when($r->date,fn($q,$v)=>$q->whereDate('appointment_date',$v))->when($r->barber_id,fn($q,$v)=>$q->where('barber_id',$v))->when($r->status,fn($q,$v)=>$q->where('status',$v))->orderByDesc('appointment_date')->orderBy('start_time')->get();}
 public function updateAppointment(Request $r,Appointment $appointment){$appointment->update($r->validate(['status'=>'sometimes|in:pending,confirmed,cancelled,completed','appointment_date'=>'sometimes|date','start_time'=>'sometimes|date_format:H:i','end_time'=>'sometimes|date_format:H:i']));return $appointment->load(['client','barber','services.service']);}
 public function schedules(){return response()->json(['schedules'=>Schedule::with('barber')->orderBy('day_of_week')->get(),'barbers'=>User::where('role','barber')->get(['id','name'])]);}
 public function updateSchedule(Request $r,Schedule $schedule){$schedule->update($r->validate(['start_time'=>'required|date_format:H:i','end_time'=>'required|date_format:H:i','break_start'=>'nullable|date_format:H:i','break_end'=>'nullable|date_format:H:i']));return $schedule;}
}
